      // element does, the trigger has been detached and nothing will ever\n        // hide this tip — drop it. (Bootstrap re-appends its cached tip element\n        // on the next show, so removing it here is safe.)\n        const trigger = tip.id\n            ? document.querySelector(`[aria-describedby=\"${tip.id}\"]`)\n            : null;\n        const inst = trigger && bs && bs.Tooltip ? bs.Tooltip.getInstance(trigger) : null;\n        if (inst) {\n            try { inst.hide(); } catch (e) { tip.remove(); }\n        } else {\n            tip.remove();\n        }\n    });\n    return tips.length > 0;\n}\n\n/** Install the global scroll safety-net. Idempotent. */\nfunction initTooltipHygiene() {\n    if (window.__whgTooltipHygiene) return;\n    window.__whgTooltipHygiene = true;\n\n    // Hint flag so the scroll handler is a no-op unless a tooltip has actually\n    // been shown since the last clean sweep. `shown.bs.tooltip` is dispatched on\n    // the trigger and does not bubble, but capture-phase listeners on `document`\n    // see every event targeted at a node in the document regardless.\n    let maybeShown = false;\n    document.addEventListener('shown.bs.tooltip', () => { maybeShown = true; }, true);\n\n    let queued = false;\n    document.addEventListener('scroll', () => {\n        if (!maybeShown || queued) return;\n        queued = true;\n        requestAnimationFrame(() => {\n            queued = false;\n            maybeShown = dismissTooltips();\n        });\n    }, {\n        // `scroll` does not bubble, so a listener on an inner scroll container\n        // (the place list, a modal body, a table) would otherwise be missed —\n        // capture catches them all with a single listener.\n        capture: true,\n        passive: true,\n    });\n\n    // Same reasoning for a full-page navigation restore / resize: the anchor\n    // geometry changes without any pointer event.\n    window.addEventListener('resize', () => { if (maybeShown) maybeShown = dismissTooltips(); }, { passive: true });\n}\n\n/** Change a tooltip's text after its trigger has been hovered at least once.\n *\n *  Setting `data-bs-title` is not enough on its own, and the reason is not\n *  obvious. base.js configures ONE delegated tooltip on <body> whose `title` is\n *  a callback reading that attribute at show time — but delegation builds a\n *  separate Tooltip instance per element on first hover, and Bootstrap's\n *  `_getDelegateConfig()` omits any config value equal to the shared Default,\n *  which is exactly where our callback lives. The per-element config therefore\n *  falls back to the `data-bs-title` data attribute, captured once as a plain\n *  string, and `getOrCreateInstance` reuses that instance for the life of the\n *  element. A toggle button relabelled on click keeps announcing the state the\n *  user has just left.\n *\n *  Disposing the instance is what actually works: it takes down any tip on\n *  screen and lets the next hover build a fresh one from the current attribute.\n */\nfunction setTooltipText(el, text) {\n    const node = (el && el.jquery) ? el[0] : el;\n    if (!node) return;\n    node.setAttribute('data-bs-title', text);\n    // Bootstrap writes this one itself when a trigger uses a plain `title`;\n    // keep it in step for anything that reads it.\n    if (node.hasAttribute('data-bs-original-title')) {\n        node.setAttribute('data-bs-original-title', text);\n    }\n    const Tip = (window.bootstrap && window.bootstrap.Tooltip) ||\n        (window.jQuery && window.jQuery.fn.tooltip && window.jQuery.fn.tooltip.Constructor);\n    try {\n        const inst = Tip && Tip.getInstance(node);\n        if (inst) inst.dispose();\n    } catch (e) { /* never yet hovered, or already disposed */ }\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///8928\n\n}")},2465(__unused_webpack_module,__unused_webpack___webpack_exports__,__webpack_require__){eval("{\n;// ./whg/webpack/js/recon-sync.js\n// recon-sync.js — network layer for collaborative Workbench projects (place#112, Phase 0/1).\n//\n// Pure fetch calls against the Django API mounted under /reconciliation/ (see workbench/urls.py).\n// Session-authenticated + CSRF (mirrors the /reconcile call in reconciliation.js). No DOM, no\n// project state — the orchestration (debounced push, conflict UI, read-only mode) lives in\n// reconciliation.js which owns the `project` object.\n\nconst BASE = '/reconciliation';\n\nfunction csrf() {\n  const input = document.querySelector('input[name=csrfmiddlewaretoken]');\n  if (input && input.value) return input.value;\n  const m = document.cookie.match(/(?:^|;\\s*)csrftoken=([^;]+)/);\n  return m ? decodeURIComponent(m[1]) : '';\n}\n\n// Low-level request. Returns { ok, status, data }. Never throws on HTTP status (callers branch on\n// status — e.g. 409 conflict is an expected, meaningful response); only network failures reject.\nasync function req(method, path, body) {\n  const opts = {\n    method,\n    credentials: 'same-origin',\n    headers: { 'X-CSRFToken': csrf() },\n  };\n  if (body !== undefined) {\n    opts.headers['Content-Type'] = 'application/json';\n    opts.body = JSON.stringify(body);\n  }\n  const res = await fetch(BASE + path, opts);\n  let data = null;\n  try { data = await res.json(); } catch (_) { /* empty/non-JSON body */ }\n  return { ok: res.ok, status: res.status, data };\n}\n\n// ── projects ────────────────────────────────────────────────────────────────\nconst listProjects = () => req('GET', '/projects/');\n// docType defaults server-side to 'reconciliation' (back-compat); Collaborative Collections editors\n// pass 'place_collection' | 'itinerary' | 'gazetteer_group' (workbench/doctypes.py).\nconst createProject = (snapshot, title, team, docType) =>\n  req('POST', '/projects/', { snapshot, title, team, doc_type: docType });\nconst fetchProject = (id) => req('GET', `/projects/${id}/`);\nconst deleteProject = (id) => req('DELETE', `/projects/${id}/`);\n\n// Publish (or re-publish) a project into its canonical model (Collection). Editor/owner only.\n// 200 { ok, status:'published', collection_id, added, unresolved:[…] }.\nconst publishProject = (id) => req('POST', `/projects/${id}/publish/`);\n\n// Check out an already-published Place Collection into a new editable project (plan §6).\n// 201 { id, version, doc_type, team }.\nconst checkoutCollection = (collectionId, team) =>\n  req('POST', `/checkout/collection/${collectionId}/`, { team });\n\n// PUT a snapshot built on `baseVersion`. Resolves to { status, data }:\n//   200 { status:'ok'|'merged', version, snapshot? }   — accepted (adopt merged snapshot if present)\n//   409 { status:'conflict', version, conflicts, merged }  — resolve + re-push at `version`\n//   409 { status:'stale', version, snapshot }              — ancestor gone; reload server copy\nconst pushSnapshot = (id, snapshot, baseVersion) =>\n  req('PUT', `/projects/${id}/`, { snapshot, base_version: baseVersion });\n\n// Mint a short-lived JWT for the Hocuspocus real-time service (Phase 2). 200 {token,document,role},\n// or 501 (realtime not configured) / 403 (not a member) → caller stays on the Phase-1 REST sync.\nconst collabToken = (id) => req('POST', `/projects/${id}/collab-token/`);\n\n// Search public, non-core published gazetteers (datasets) for the Gazetteer Group editor.\n// 200 { datasets:[{id, title, label, description}] }.\nconst searchDatasets = (q) => req('GET', '/datasets/search/?q=' + encodeURIComponent(q || ''));\n\n// Fetch a shared Google Sheet as CSV via the server-side proxy (avoids browser CORS).\nconst importGSheet = (url) => req('POST', '/gsheet/', { url });\nconst importGDoc = (url) => req('POST', '/gdoc/', { url });\n\n// Place-name extraction. Sends text to the small language model running on WHG's own server — the\n// one Map-your-Data step that leaves the browser. Returns { entities:[{name,label,count,context}] }.\nconst ner = (text) => req('POST', '/ner/', { text });\n// Per-row extraction for the column operation (place#211). Each row carries its own container, so a\n// table whose rows sit in different counties is scoped row by row rather than by one global region.\n// Batched by the caller — the server caps a request at ten rows.\nconst nerRows = (rows, fallbackContainedIn) =>\n  req('POST', '/ner/rows/', { rows, fallback_contained_in: fallbackContainedIn || [] });\n\n// ── sharing (Phase 0) ─────────────────────────────────────────────────────────\nconst shareProject = (id) => req('POST', `/projects/${id}/share/`);\nconst unshareProject = (id) => req('DELETE', `/projects/${id}/share/`);\nconst fetchShared = (token) => req('GET', `/shared/${token}/`);\n\n// ── teams ───────────────────────────────────────────────────────────────────\nconst listTeams = () => req('GET', '/teams/');\nconst createTeam = (title, description) => req('POST', '/teams/', { title, description });\nconst listMembers = (teamId) => req('GET', `/teams/${teamId}/members/`);\nconst addMember = (teamId, identifier, role, projectId) =>\n  req('POST', `/teams/${teamId}/members/`, { identifier, role, project_id: projectId });\nconst removeMember = (teamId, uid) => req('DELETE', `/teams/${teamId}/members/${uid}/`);\n\n;// ./whg/webpack/js/wb-shell.js\n// wb-shell.js — shared primitives for Collaborative Workbench doc-type editors.\n//\n// The plan (plan-collaborativeCollections §3.3) calls for one shell shared by every doc-type editor:\n// local-first IndexedDB persistence, an autosave/\"saved\" badge, CSRF, and small DOM helpers. This is\n// a fresh, focused implementation the new editors build on (starting with wb-place-collection.js).\n// The large existing Map-your-Data tool (reconciliation.js) can migrate onto this module later; it is\n// deliberately dependency-light and framework-free so that migration is mechanical.\n//\n// What lives here: the plumbing that is identical across doc-types. What does NOT: the panes/controls\n// specific to a doc-type (those live in the doc-type editor + its template).\n\n\n\n// ── DOM + text helpers ────────────────────────────────────────────────────────\nconst el = (id) => document.getElementById(id);\nconst esc = (s) => String(s == null ? '' : s)\n  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')\n  .replace(/\"/g, '&quot;').replace(/'/g, '&#39;');\nconst truncate = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };\n\n// Great-circle distance in km between two [lng, lat] points. Used to score suggestions by\n// colocation with already-selected members (a collection's places tend to cluster geographically).\nfunction haversineKm(a, b) {\n  if (!a || !b || a[0] == null || b[0] == null) return Infinity;\n  const R = 6371, rad = Math.PI / 180;\n  const dLat = (b[1] - a[1]) * rad, dLon = (b[0] - a[0]) * rad;\n  const s = Math.sin(dLat / 2) ** 2 + Math.cos(a[1] * rad) * Math.cos(b[1] * rad) * Math.sin(dLon / 2) ** 2;\n  return 2 * R * Math.asin(Math.min(1, Math.sqrt(s)));\n}\n\n// Mean [lng, lat] of a list of [lng, lat] points (ignoring nulls); null if none.\nfunction centroid(points) {\n  const pts = (points || []).filter((p) => p && p[0] != null && p[1] != null);\n  if (!pts.length) return null;\n  return [pts.reduce((s, p) => s + p[0], 0) / pts.length, pts.reduce((s, p) => s + p[1], 0) / pts.length];\n}\n\nfunction debounce(fn, ms) {\n  let t = null;\n  const wrapped = (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };\n  wrapped.flush = (...args) => { clearTimeout(t); fn(...args); };\n  return wrapped;\n}\n\n// ── accordion (sole-open panes) ────────────────────────────────────────────────\n// Mirrors the Map-your-Data pane accordion (reconciliation.js openPane): panes use the shared\n// `.recon-pane` / `.recon-pane-toggle[data-pane]` markup from reconciliation.css; opening one adds\n// `.recon-collapsed` to every other. Coloured step-number badges come from per-pane CSS in the\n// editor template.\nfunction openPane(id) {\n  document.querySelectorAll('.recon-pane').forEach((p) => p.classList.toggle('recon-collapsed', p.id !== id));\n}\n\nfunction mountAccordion(openId, onOpen) {\n  document.querySelectorAll('.recon-pane-toggle').forEach((btn) => btn.addEventListener('click', () => {\n    const p = btn.closest('.recon-pane');\n    if (!p) return;\n    if (p.classList.contains('recon-collapsed')) { openPane(p.id); if (onOpen) onOpen(p.id); } // sole-open\n    else p.classList.add('recon-collapsed');                                                   // click again collapses\n  }));\n  if (openId) openPane(openId);\n}\n\n// Shared numbered-marker palette (matches reconciliation.js RECON_COLORS + recon-map.js COLORS) so\n// list badges and map pins line up across the Workbench.\nconst WB_COLORS = (/* unused pure expression or super */ null && (['#1565c0', '#c2410c', '#2e7d32', '#6a1b9a', '#00838f', '#b26a00', '#455a64', '#c2185b', '#5d4037']));\n\n// Copy text to the clipboard; resolves true/false. Falls back to a hidden textarea+execCommand when\n// the async Clipboard API is unavailable (older browsers / insecure context).\nasync function copyToClipboard(text) {\n  try {\n    if (navigator.clipboard && window.isSecureContext) { await navigator.clipboard.writeText(text); return true; }\n  } catch (_) { /* fall through */ }\n  try {\n    const ta = document.createElement('textarea');\n    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';\n    document.body.appendChild(ta); ta.select();\n    const ok = document.execCommand('copy'); document.body.removeChild(ta); return ok;\n  } catch (_) { return false; }\n}\n\nfunction wb_shell_csrf() {\n  const input = document.querySelector('input[name=csrfmiddlewaretoken]');\n  if (input && input.value) return input.value;\n  const m = document.cookie.match(/(?:^|;\\s*)csrftoken=([^;]+)/);\n  return m ? decodeURIComponent(m[1]) : '';\n}\n\n// ── local-first project store (IndexedDB, one current draft per browser) ───────\n// Mirrors the Map-your-Data store contract (single \"current\" project per DB) so behaviour and mental\n// model match. A doc-type editor picks its own dbName so drafts of different types don't collide.\nfunction openStore(dbName, storeName = 'project', key = 'current') {\n  const open = () => new Promise((resolve, reject) => {\n    const req = indexedDB.open(dbName, 1);\n    req.onupgradeneeded = () => { if (!req.result.objectStoreNames.contains(storeName)) req.result.createObjectStore(storeName); };\n    req.onsuccess = () => resolve(req.result);\n    req.onerror = () => reject(req.error);\n  });\n  const tx = async (mode, fn) => {\n    const db = await open();\n    return new Promise((resolve, reject) => {\n      const t = db.transaction(storeName, mode);\n      const store = t.objectStore(storeName);\n      const r = fn(store);\n      t.oncomplete = () => resolve(r && r.result);\n      t.onerror = () => reject(t.error);\n    });\n  };\n  return {\n    load: () => tx('readonly', (s) => s.get(key)),\n    save: (project) => tx('readwrite', (s) => s.put(project, key)),\n    clear: () => tx('readwrite', (s) => s.delete(key)),\n  };\n}\n\n// ── saved/saving/error status badge ────────────────────────────────────────────\nfunction statusBadge(node) {\n  if (!node) return { saved() {}, saving() {}, error() {}, offline() {} };\n  const set = (cls, txt) => { node.className = 'wb-status ' + cls; node.textContent = txt; };\n  return {\n    saving() { set('wb-status--saving', 'Saving…'); },\n    saved() { set('wb-status--saved', 'Saved in your browser'); },\n    synced() { set('wb-status--saved', 'Saved to your account'); },\n    error(msg) { set('wb-status--error', msg || 'Save failed'); },\n    offline() { set('wb-status--saved', 'Saved locally'); },\n  };\n}\n\n// ── server bridge (optional; local-first works with none of this) ──────────────\n// A thin wrapper over recon-sync giving editors a uniform create/push/publish surface that carries\n// doc_type and tracks the server id + version for optimistic-lock pushes.\nfunction serverBridge(docType) {\n  const state = { id: null, version: 0 };\n  return {\n    get id() { return state.id; },\n    setServer(id, version) { state.id = id; state.version = version || 0; },\n    async create(snapshot, title, team) {\n      const r = await createProject(snapshot, title, team, docType);\n      if (r.ok && r.data && r.data.id) { state.id = r.data.id; state.version = r.data.version || 1; }\n      return r;\n    },\n    async push(snapshot) {\n      if (!state.id) return { ok: false, status: 0, data: { error: 'not saved to account yet' } };\n      const r = await pushSnapshot(state.id, snapshot, state.version);\n      if (r.ok && r.data && typeof r.data.version === 'number') state.version = r.data.version;\n      return r;\n    },\n    async load(id) {\n      const r = await fetchProject(id);\n      if (r.ok && r.data) { state.id = id; state.version = r.data.version || 0; }\n      return r;\n    },\n    publish() { return publishProject(state.id); },\n  };\n}\n\n;// ./whg/webpack/js/typeTreeWidget.js\n// /whg/webpack/js/typeTreeWidget.js\n/**\n * Lightweight hierarchical type-tree widget for AAT place types.\n *\n * Loads data lazily from /types/tree/ and /types/tree/<aat_id>/,\n * renders an expandable tree with tri-state checkboxes, and exposes\n * the minimal set of selected AAT identifiers (parent selection implies\n * all descendants — the server expands via expand_type_identifiers).\n *\n * Includes an inline search box that queries /types/tree/search/?q=...\n * and expands the tree to reveal matched nodes.\n *\n * Usage:\n *   import TypeTreeWidget from './typeTreeWidget';\n *   const tree = new TypeTreeWidget('#aat_type_tree', {\n *       onchange: () => { ... },\n *   });\n */\n\n\n\nconst TREE_URL = '/types/tree/';\n\n/**\n * Turn a rejected jqXHR (or a thrown Error) into a one-line description.\n * jQuery rejects with the jqXHR object, which stringifies to \"[object Object]\" —\n * useless in a GlitchTip report from a beta tester whose tree failed to load.\n */\nfunction describeError(url, err) {\n    if (err && typeof err.status !== 'undefined') {\n        return `${url} — ${err.status ? 'HTTP ' + err.status : 'no response'}` +\n            `${err.statusText ? ' (' + err.statusText + ')' : ''}`;\n    }\n    return `${url} — ${(err && err.message) || err}`;\n}\n\n/** Surface a client-side failure in GlitchTip, when the SDK is loaded. */\nfunction reportError(message) {\n    if (window.Sentry && typeof window.Sentry.captureException === 'function') {\n        window.Sentry.captureException(new Error(message));\n    }\n}\n\n/** GeoNames feature-class labels shown as badge tooltips. */\nconst FCLASS_LABELS = {\n    A: 'Administrative divisions',\n    H: 'Hydrographic features',\n    L: 'Area features',\n    P: 'Populated places',\n    R: 'Road / railroad features',\n    S: 'Spot features',\n    T: 'Hypsographic features',\n    U: 'Undersea features',\n    V: 'Vegetation features',\n};\n\nclass TypeTreeWidget {\n\n    /**\n     * @param {string|HTMLElement} container - CSS selector or element\n     * @param {Object}  opts\n     * @param {Function} opts.onchange - Called whenever selections change\n     */\n    constructor(container, opts = {}) {\n        this.$el = $(container);\n        this._onchange = opts.onchange || function () {};\n        this._initialised = false;\n        this._searchTimer = null;\n        // Concepts selected but not (yet) materialised in the lazily-loaded tree —\n        // id → label. Lets the widget round-trip a caller-supplied selection\n        // (setSelected) and still report it (getSelectedConcepts) before the\n        // relevant branch has been expanded. Used by the Map-your-Data + Workbench\n        // pickers (place#134); the Atlas filter never sets it.\n        this._pending = new Map();\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Public API\n     * ------------------------------------------------------------ */\n\n    /** Lazily initialise: fetch root nodes on first call. */\n    async init() {\n        if (this._initialised) return;\n        this._initialised = true;\n        console.log('TypeTreeWidget: initialising, fetching', TREE_URL);\n        this.$el.html(\n            '<div class=\"tt-loading\"><i class=\"fas fa-spinner fa-spin\"></i> Loading types…</div>'\n        );\n        try {\n            const nodes = await $.getJSON(TREE_URL);\n            console.log('TypeTreeWidget: received', nodes.length, 'root nodes');\n            this.$el.empty();\n            if (!nodes.length) {\n                this.$el.html(\n                    '<div class=\"tt-error\">No place types found. Run <code>manage.py sync_aat_types</code>.</div>'\n                );\n                return;\n            }\n\n            // --- Search box (sticky at top of scrollable container) ---\n            const $searchWrap = $(`\n                <div class=\"tt-search\">\n                    <div class=\"tt-search-input-wrap\">\n                        <input type=\"text\" class=\"tt-search-input form-control form-control-sm\"\n                               placeholder=\"Search place types…\" autocomplete=\"off\" spellcheck=\"false\">\n                        <span class=\"tt-search-clear\" title=\"Clear\">&times;</span>\n                    </div>\n                </div>\n            `);\n            // Results dropdown lives on <body> so it isn't clipped by\n            // the overflow:auto tree container.\n            this._$searchResults = $('<div class=\"tt-search-results\"></div>')\n                .appendTo(document.body);\n            this.$el.append($searchWrap);\n            this._setupSearch($searchWrap);\n\n            // --- Tree ---\n            const $root = $('<ul class=\"tt-root\"></ul>');\n            nodes.forEach(n => $root.append(this._renderNode(n)));\n            this.$el.append($root);\n\n            // Auto-expand all root-level nodes that have children\n            const $rootNodes = $root.children('.tt-node');\n            for (let i = 0; i < $rootNodes.length; i++) {\n                const $li = $rootNodes.eq(i);\n                if ($li.children('.tt-children').length > 0) {\n                    await this._toggle($li);\n                    // Show immediately without slide animation for initial load\n                    $li.children('.tt-children').stop(true, true).show();\n                }\n            }\n\n            // Apply any selection set before init (setSelected called early).\n            this._applyPending(this.$el);\n\n            // Initialise Bootstrap tooltips on all badges rendered so far\n            this._initTooltips(this.$el);\n        } catch (err) {\n            const detail = describeError(TREE_URL, err);\n            console.error('TypeTreeWidget: failed to load root nodes — ' + detail);\n            reportError('TypeTreeWidget root load failed: ' + detail);\n            this.$el.html(\n                '<div class=\"tt-error\">Could not load place types.</div>'\n            );\n        }\n    }\n\n    /**\n     * Return the minimal set of selected AAT identifier strings.\n     *\n     * When a parent is fully checked, only the parent is returned\n     * (the server calls expand_type_identifiers to include descendants).\n     * Partially checked subtrees return only the checked leaves / subtrees.\n     */\n    getSelectedIdentifiers() {\n        if (!this._initialised) return [];\n        return this._collectSelected(\n            this.$el.find('> .tt-root > .tt-node')\n        );\n    }\n\n    /** True when the user has made at least one explicit selection. */\n    hasSelections() {\n        return this.$el.find('.tt-cb:checked').length > 0 ||\n            this.$el.find('.tt-cb').filter(function () {\n                return this.indeterminate;\n            }).length > 0;\n    }\n\n    /** Number of individually checked checkboxes (for the badge). */\n    selectionCount() {\n        return this.$el.find('.tt-cb:checked').length;\n    }\n\n    /** Clear every checkbox. */\n    clearAll() {\n        this._pending = new Map();\n        this.$el.find('.tt-cb')\n            .prop('checked', false)\n            .prop('indeterminate', false);\n        this.$el.find('.tt-highlight').removeClass('tt-highlight');\n        this._onchange();\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Selection round-tripping (chip-based pickers — place#134)\n     * ------------------------------------------------------------ */\n\n    /**\n     * Return the minimal selected set as ``[{id: 'aat:<id>', text}]`` — the same\n     * minimal set as getSelectedIdentifiers(), but carrying each concept's label\n     * (from the rendered node, or a caller-supplied fallback / pending label).\n     * Includes selections not yet rendered in the lazily-loaded tree.\n     *\n     * @param {Object} [labelFallback] - id → label used when a node isn't in the DOM\n     */\n    getSelectedConcepts(labelFallback) {\n        const out = [];\n        const seen = new Set();\n        if (this._initialised) {\n            const walk = ($nodes) => {\n                $nodes.each((_, el) => {\n                    const $n = $(el);\n                    const $cb = $n.children('.tt-cb');\n                    if ($cb.prop('checked')) {\n                        const id = $cb.val();\n                        if (!seen.has(id)) { seen.add(id); out.push({ id, text: this._labelOf($n, id, labelFallback) }); }\n                    } else if ($cb.prop('indeterminate') || $cb.length === 0) {\n                        // No checkbox at all = a facet row: never selected itself, always\n                        // descended into, or the concepts beneath it are invisible here.\n                        walk($n.children('.tt-children').children('.tt-node'));\n                    }\n                });\n            };\n            walk(this.$el.find('> .tt-root > .tt-node'));\n        }\n        // Selections whose node hasn't been rendered yet (never expanded to).\n        this._pending.forEach((text, id) => {\n            if (!seen.has(id)) { seen.add(id); out.push({ id, text: text || (labelFallback && labelFallback[id]) || '' }); }\n        });\n        return out;\n    }\n\n    /**\n     * Replace the selection with ``concepts`` (``[{id, text}]`` or bare id strings).\n     * Any concept whose node is already rendered is checked immediately (cascading\n     * to descendants); the rest are held in ``_pending`` and applied as their\n     * branch is expanded. Fires onchange.\n     */\n    setSelected(concepts) {\n        this._pending = new Map();\n        (concepts || []).forEach((c) => {\n            const id = (c && c.id) ? c.id : c;\n            if (id) this._pending.set(id, (c && c.text) || '');\n        });\n        if (this._initialised) {\n            this.$el.find('.tt-cb').prop('checked', false).prop('indeterminate', false);\n            this._applyPending(this.$el);\n        }\n        this._onchange();\n    }\n\n    /** Deselect one concept by id (``aat:<id>``). Fires onchange. */\n    deselect(id) {\n        this._pending.delete(id);\n        if (this._initialised) {\n            const $node = this.$el.find('.tt-node').filter(function () { return $(this).attr('data-id') === id; });\n            if ($node.length) {\n                $node.children('.tt-cb').prop('checked', false).prop('indeterminate', false);\n                $node.find('.tt-cb').prop('checked', false).prop('indeterminate', false);\n                this._updateAncestors($node);\n            }\n        }\n        this._onchange();\n    }\n\n    /** Apply any pending selections that now have a rendered node within $scope. */\n    _applyPending($scope) {\n        if (!this._pending.size) return;\n        const self = this;\n        const touched = [];\n        ($scope || this.$el).find('.tt-node').each(function () {\n            const $li = $(this);\n            const id = $li.attr('data-id');\n            if (id && self._pending.has(id)) {\n                const $cb = $li.children('.tt-cb');\n                if ($cb.length) {\n                    $cb.prop('checked', true).prop('indeterminate', false);\n                    // Cascade to any already-loaded descendants (later-loaded ones\n                    // inherit via the parentChecked branch in _toggle).\n                    $li.find('.tt-cb').prop('checked', true).prop('indeterminate', false);\n                    self._pending.delete(id);\n                    touched.push($li);\n                }\n            }\n        });\n        touched.forEach(($li) => this._updateAncestors($li));\n    }\n\n    /** Best label for a node: its rendered text, else a fallback map, else ''. */\n    _labelOf($n, id, labelFallback) {\n        const t = ($n.children('.tt-label').text() || '').trim();\n        if (t) return t;\n        if (labelFallback && labelFallback[id]) return labelFallback[id];\n        return '';\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Internal: rendering\n     * ------------------------------------------------------------ */\n\n    _renderNode(node) {\n        const hasChildren = node.children === true;\n        const isGuide = !!node.guide;\n        const $li = $('<li class=\"tt-node\"></li>')\n            .attr('data-id', node.id)\n            .attr('data-aat-id', node.aat_id);\n\n        if (isGuide) $li.addClass('tt-guide');\n\n        // Toggle arrow (only when the node can have children)\n        const $toggle = hasChildren\n            ? $('<span class=\"tt-toggle\"><i class=\"fas fa-caret-right\"></i></span>')\n            : $('<span class=\"tt-toggle tt-leaf\"></span>');\n\n        // Checkbox — guide (organisational) nodes are not selectable\n        const $cb = isGuide\n            ? null\n            : $(`<input type=\"checkbox\" class=\"tt-cb\" value=\"${node.id}\">`);\n\n        // Label\n        const $label = $(`<span class=\"tt-label\">${this._esc(node.text)}</span>`);\n\n        // fclass badges\n        const badges = (node.fclasses || []).map(\n            f => {\n                const key = f.toUpperCase();\n                const label = FCLASS_LABELS[key] || key;\n                const tip = `<b>GeoNames class <em>${this._esc(key)}</em></b><br>${this._esc(label)}`;\n                return `<span class=\"tt-badge tt-badge-${f.toLowerCase()}\"\n                    data-bs-toggle=\"tooltip\" data-bs-html=\"true\"\n                    data-bs-title=\"${tip}\">${f}</span>`;\n            }\n        ).join('');\n\n        if ($cb) {\n            $li.append($toggle, $cb, ' ', $label, ' ', badges);\n        } else {\n            $li.append($toggle, ' ', $label, ' ', badges);\n        }\n\n        if (hasChildren) {\n            // Start hidden so the first toggle opens correctly\n            $li.append('<ul class=\"tt-children\" style=\"display:none\"></ul>');\n            $li.data('loaded', false);\n        }\n\n        // --- Events ---\n\n        // Expand / collapse\n        $toggle.add($label).on('click', (e) => {\n            e.preventDefault();\n            if (hasChildren) this._toggle($li);\n        });\n\n        // Checkbox cascade (only for non-guide nodes)\n        if ($cb) {\n            $cb.on('change', () => {\n                const checked = $cb.prop('checked');\n                // Cascade down (only to non-guide checkboxes)\n                $li.find('.tt-cb')\n                    .prop('checked', checked)\n                    .prop('indeterminate', false);\n                // Cascade up\n                this._updateAncestors($li);\n                this._onchange();\n            });\n        }\n\n        return $li;\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Internal: expand / collapse with lazy loading\n     * ------------------------------------------------------------ */\n\n    async _toggle($li) {\n        const $children = $li.children('.tt-children');\n        const $icon = $li.children('.tt-toggle').find('i');\n\n        if ($children.is(':visible')) {\n            $children.slideUp(120);\n            $icon.removeClass('fa-caret-down').addClass('fa-caret-right');\n            return;\n        }\n\n        // Lazy-load children on first expand\n        if (!$li.data('loaded')) {\n            const aatId = $li.data('aat-id');\n            $icon.removeClass('fa-caret-right').addClass('fa-spinner fa-spin');\n            try {\n                const nodes = await $.getJSON(`${TREE_URL}${aatId}/`);\n                const parentChecked = $li.children('.tt-cb').prop('checked');\n                if (nodes.length === 0) {\n                    // No children after all — mark as leaf\n                    $li.children('.tt-toggle')\n                        .addClass('tt-leaf')\n                        .find('i').remove();\n                    $li.data('loaded', true);\n                    $icon.removeClass('fa-spinner fa-spin');\n                    return;\n                }\n                nodes.forEach(n => {\n                    const $child = this._renderNode(n);\n                    if (parentChecked) {\n                        $child.children('.tt-cb').prop('checked', true);\n                    }\n                    $children.append($child);\n                });\n                $li.data('loaded', true);\n                // Check any pending selections that live in this newly-loaded branch.\n                this._applyPending($children);\n                // Initialise Bootstrap tooltips on newly loaded children\n                this._initTooltips($children);\n            } catch (err) {\n                const detail = describeError(TREE_URL + aatId + '/', err);\n                console.error('TypeTreeWidget: load failed for ' + aatId + ' — ' + detail);\n                reportError('TypeTreeWidget branch load failed: ' + detail);\n            }\n            $icon.removeClass('fa-spinner fa-spin');\n        }\n\n        $icon.removeClass('fa-caret-right').addClass('fa-caret-down');\n        $children.slideDown(120);\n    }\n\n    /** Expand a node if it is collapsed; no-op if already open or a leaf. */\n    async _ensureExpanded($li) {\n        const $children = $li.children('.tt-children');\n        if ($children.length === 0) return;  // leaf\n        if ($children.is(':hidden')) {\n            await this._toggle($li);\n        }\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Internal: tri-state checkbox propagation\n     * ------------------------------------------------------------ */\n\n    /**\n     * The selectable children of ``$node``, looking straight through facet rows.\n     *\n     * The AAT tree interleaves grouping rows (``li.tt-node.tt-guide`` — the italic\n     * \"by biome\", \"by form\", \"by condition\") which organise concepts but carry no\n     * checkbox of their own. Treating them as ordinary children makes a parent look\n     * as though it has zero selectable children, which silently broke every walk\n     * below: no ancestor was ever marked indeterminate, so a concept ticked beneath a\n     * facet row read back as no selection at all (place#223). They are organisational,\n     * not selectable, so every walk has to see through them.\n     */\n    _conceptChildren($node) {\n        let out = $();\n        $node.children('.tt-children').children('.tt-node').each((_, el) => {\n            const $c = $(el);\n            if ($c.children('.tt-cb').length) out = out.add($c);\n            else out = out.add(this._conceptChildren($c));\n        });\n        return out;\n    }\n\n    _updateAncestors($li) {\n        const $parent = $li.parent('.tt-children').closest('.tt-node');\n        if ($parent.length === 0) return;\n\n        const $childCbs = this._conceptChildren($parent).children('.tt-cb');\n        const total = $childCbs.length;\n\n        // A facet row has no checkbox of its own: `$pcb` is empty, the `.prop()` calls\n        // below are no-ops, and what matters is that we keep climbing to the real\n        // concept above it rather than stopping here.\n        if (total > 0) {\n            let checked = 0;\n            let indeterminate = 0;\n            $childCbs.each(function () {\n                if (this.checked) checked++;\n                if (this.indeterminate) indeterminate++;\n            });\n\n            const $pcb = $parent.children('.tt-cb');\n            if (checked === total && indeterminate === 0) {\n                $pcb.prop({ checked: true, indeterminate: false });\n            } else if (checked === 0 && indeterminate === 0) {\n                $pcb.prop({ checked: false, indeterminate: false });\n            } else {\n                $pcb.prop({ checked: false, indeterminate: true });\n            }\n        }\n\n        // Keep walking up\n        this._updateAncestors($parent);\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Internal: collect the minimal selected-identifier set\n     * ------------------------------------------------------------ */\n\n    _collectSelected($nodes) {\n        const ids = [];\n        $nodes.each((_, el) => {\n            const $n = $(el);\n            const $cb = $n.children('.tt-cb');\n            if ($cb.prop('checked')) {\n                // Whole subtree implied → return just this node\n                ids.push($cb.val());\n            } else if ($cb.prop('indeterminate') || $cb.length === 0) {\n                // Partial, or a facet row that carries no checkbox → recurse into children\n                const $childNodes = $n.children('.tt-children').children('.tt-node');\n                ids.push(...this._collectSelected($childNodes));\n            }\n            // unchecked → skip\n        });\n        return ids;\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Search\n     * ------------------------------------------------------------ */\n\n    _setupSearch($wrap) {\n        const $input = $wrap.find('.tt-search-input');\n        const $results = this._$searchResults;\n        const $clear = $wrap.find('.tt-search-clear');\n        let activeIndex = -1;\n\n        const positionDropdown = () => {\n            const rect = $input[0].getBoundingClientRect();\n            $results.css({\n                top:   rect.bottom + 'px',\n                left:  rect.left   + 'px',\n                width: rect.width  + 'px',\n            });\n        };\n\n        const hideResults = () => {\n            $results.hide();\n            activeIndex = -1;\n        };\n\n        const highlightActive = () => {\n            $results.find('.tt-search-item').removeClass('tt-search-active');\n            if (activeIndex >= 0) {\n                const $active = $results.find('.tt-search-item').eq(activeIndex);\n                $active.addClass('tt-search-active');\n                // Scroll into view within the dropdown\n                const el = $active[0];\n                if (el) el.scrollIntoView({ block: 'nearest' });\n            }\n        };\n\n        const clearSearch = () => {\n            $input.val('');\n            hideResults();\n            $results.empty();\n            $clear.hide();\n            this.$el.find('.tt-highlight').removeClass('tt-highlight');\n        };\n\n        $input.on('input', () => {\n            clearTimeout(this._searchTimer);\n            activeIndex = -1;\n            const q = $input.val().trim();\n            $clear.toggle(q.length > 0);\n            if (q.length < 2) {\n                hideResults();\n                $results.empty();\n                return;\n            }\n            this._searchTimer = setTimeout(() => {\n                this._fetchSearchResults(q, $results, positionDropdown);\n            }, 300);\n        });\n\n        $input.on('keydown', (e) => {\n            const $items = $results.find('.tt-search-item');\n            const count = $items.length;\n\n            if (e.key === 'Escape') {\n                clearSearch();\n                return;\n            }\n\n            if (!$results.is(':visible') || count === 0) return;\n\n            if (e.key === 'ArrowDown') {\n                e.preventDefault();\n                activeIndex = Math.min(activeIndex + 1, count - 1);\n                highlightActive();\n            } else if (e.key === 'ArrowUp') {\n                e.preventDefault();\n                activeIndex = Math.max(activeIndex - 1, 0);\n                highlightActive();\n            } else if (e.key === 'Enter') {\n                e.preventDefault();\n                if (activeIndex >= 0 && activeIndex < count) {\n                    $items.eq(activeIndex).trigger('mousedown');\n                }\n            }\n        });\n\n        $clear.hide().on('click', clearSearch);\n\n        // Close results dropdown on outside click\n        $(document).on('mousedown', (e) => {\n            if (!$(e.target).closest('.tt-search').length &&\n                !$(e.target).closest('.tt-search-results').length) {\n                hideResults();\n            }\n        });\n\n        // Hide when the page scrolls (the fixed dropdown would be misaligned)\n        $(window).on('scroll', hideResults);\n    }\n\n    async _fetchSearchResults(query, $results, positionDropdown) {\n        try {\n            const data = await $.getJSON(`${TREE_URL}search/?q=${encodeURIComponent(query)}`);\n            $results.empty();\n            if (!data.length) {\n                $results.html('<div class=\"tt-search-empty\">No matching types</div>');\n                positionDropdown();\n                $results.show();\n                return;\n            }\n            data.forEach(item => {\n                const $item = $(`<div class=\"tt-search-item\">${this._esc(item.text)}</div>`);\n                $item.on('mousedown', async (e) => {\n                    e.preventDefault();\n                    $results.hide();\n                    this.$el.find('.tt-highlight').removeClass('tt-highlight');\n                    await this._expandToNode(item.aat_id, item.ancestors);\n                });\n                $results.append($item);\n            });\n            positionDropdown();\n            $results.show();\n        } catch (err) {\n            console.error('TypeTreeWidget: search failed', err);\n        }\n    }\n\n    /**\n     * Walk the ancestor path, expanding each node in turn, then\n     * highlight and scroll to the target node.\n     */\n    async _expandToNode(targetAatId, ancestors) {\n        for (const aat of ancestors) {\n            if (aat === targetAatId) break;\n            const $node = this.$el.find(`[data-aat-id=\"${aat}\"]`);\n            if ($node.length === 0) continue;  // skip nodes not in display tree\n            await this._ensureExpanded($node);\n        }\n\n        const $target = this.$el.find(`[data-aat-id=\"${targetAatId}\"]`);\n        if ($target.length) {\n            $target.addClass('tt-highlight');\n            // Scroll the tree container so the target is visible\n            const container = this.$el.closest('#type_tree_container')[0];\n            if (container) {\n                const targetEl = $target[0];\n                const cRect = container.getBoundingClientRect();\n                const tRect = targetEl.getBoundingClientRect();\n                if (tRect.top < cRect.top || tRect.bottom > cRect.bottom) {\n                    container.scrollTop += (tRect.top - cRect.top) - (cRect.height / 2) + (tRect.height / 2);\n                }\n            }\n        }\n    }\n\n    /* ------------------------------------------------------------ *\n     *  Helpers\n     * ------------------------------------------------------------ */\n\n    _esc(str) {\n        const d = document.createElement('div');\n        d.textContent = str;\n        return d.innerHTML;\n    }\n\n    /** Activate Bootstrap 5 tooltips on [data-bs-toggle=\"tooltip\"] inside $container. */\n    _initTooltips($container) {\n        if (typeof bootstrap === 'undefined' || !bootstrap.Tooltip) return;\n        $container.find('[data-bs-toggle=\"tooltip\"]').each(function () {\n            if (!bootstrap.Tooltip.getInstance(this)) {\n                new bootstrap.Tooltip(this);\n            }\n        });\n    }\n}\n\n\n;// ./whg/webpack/js/locus_recipe.js\n// locus_recipe.js — browser twin of places/locus_recipe.py (place#172, place#325 Stage 1).\n//\n// ONE serialisation serves both the unminted soft-cluster URL (a token of the canonical\n// bytes, re-run on every visit) and the locus PID (sha256 of exactly those bytes). The\n// specification lives in the Python module's docstring; this file implements the same\n// rules so a cluster card can build the same token the server would. Parity is proved by\n// scripts/check-locus-recipe.mjs against scripts/fixtures/locus_recipe_vectors.json — if\n// you change a rule here, change it there and regenerate the vectors.\n//\n// No DOM, no dependencies. Runs in the browser and under Node (>= 20).\n\nconst RECIPE_VERSION = 1;\n\nconst SCALAR_DP = 4;\nconst COORD_DP = 6;\nconst SIZE_MAX = 10000;\nconst YEAR_ABS_MAX = 1000000;\nconst TOKEN_MAX_BYTES = 65536;\nconst PID_HASH_BITS = 54;      // 31**11 > 2**54, so 11 base-31 digits hold them exactly\nconst PID_DIGITS = 11;\n\nconst MODES = (/* unused pure expression or super */ null && (['exact', 'starts', 'in', 'fuzzy', 'phonetic']));\nconst CONTAINMENTS = (/* unused pure expression or super */ null && (['fuzzy', 'exact']));\nconst RELATIONS = (/* unused pure expression or super */ null && (['intersects', 'within']));\nconst TEMPORAL_MODES = (/* unused pure expression or super */ null && (['possibly', 'definitely']));\nconst WEIGHT_KEYS = (/* unused pure expression or super */ null && (['link', 'name', 'spatial', 'temporal', 'type']));\n\nconst PID_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXY';   // Crockford base32 minus Z: 31 symbols\nconst PID_RE = /^[0-9A-HJKMNP-TV-Y]{4}-[0-9A-HJKMNP-TV-Y]{4}-[0-9A-HJKMNP-TV-Y]{4}$/;\nconst LEGACY_RE = /^1[0-9]{7}$/;\n\nconst FORBIDDEN_KEYS = new Set([\n\t'edges', 'edge', 'links', 'hard_links', 'merges', 'merge', 'forced_merges',\n\t'accept', 'accepted', 'acceptances', 'reject', 'rejected', 'rejections',\n\t'must_link', 'cannot_link', 'pins', 'pinned', 'attestations',\n]);\n\nconst TOP_KEYS = new Set(['v', 'retrieval', 'clustering', 'members']);\nconst RETRIEVAL_KEYS = new Set(['query', 'mode', 'size', 'ccodes', 'types', 'aat_types', 'namespaces',\n\t'bounds', 'contained_in', 'containment', 'relation', 'temporal']);\nconst TEMPORAL_KEYS = new Set(['start', 'end', 'mode', 'undated']);\nconst CLUSTERING_KEYS = new Set(['weights', 'theta', 'tau_name', 'tau_link', 'same_ns_penalty',\n\t'respect_distinct']);\n// Ruled out of the recipe (place#325 Stage 1 ruling 3, SG 2026-10-21): the generic-name\n// stoplist is gateway data, taken from the gateway response at resolve time, not hashed.\n// Rejected with a reason so an old caller fails loudly. Same text as the Python module.\nconst RETIRED_CLUSTERING_KEYS = (/* unused pure expression or super */ null && ({\n\tstoplist: 'is not part of a recipe: the generic-name stoplist is gateway data, taken '\n\t\t+ 'from the gateway response at resolve time (place#325 ruling 3, 2026-10-21)',\n}));\n\n// Exactly \\s, written out so it is visibly the same class as the Python regex.\nconst WS_RE = /[\\t\\n\\v\\f\\r \\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000\\ufeff]+/g;\nconst CCODE_RE = /^[A-Z]{2}$/;\nconst NAMESPACE_RE = /^[a-z0-9_]+$/;\nconst PLACE_ID_RE = /^([A-Za-z0-9_]+):(\\S+)$/;\nconst TOKEN_RE = /^[A-Za-z0-9_-]+$/;\n\nclass RecipeError extends Error {\n\tconstructor(path, message) {\n\t\tsuper(path ? `${path}: ${message}` : message);\n\t\tthis.name = 'R